def _use_schema() -> str:
    schema = os.getenv("AI_POSTGRES_SCHEMA", "qq_bot").strip() or "qq_bot"
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", schema):
        raise RuntimeError("Invalid PostgreSQL schema")
    quoted = op.get_bind().dialect.identifier_preparer.quote(schema)
    op.execute(f"SET LOCAL search_path TO {quoted}, public")
    return schema


def upgrade() -> None:
    schema = _use_schema()
    for table, constraint, _ in _LIVE_FOREIGN_KEYS:
        op.execute(f"ALTER TABLE {table} DROP CONSTRAINT {constraint}")
    op.execute("ALTER TABLE qq_official_background_commands DROP CONSTRAINT qq_official_background_commands_notification_action_id_fkey")
    op.execute("ALTER TABLE qq_official_program_wakes DROP CONSTRAINT qq_official_program_wakes_reply_action_id_fkey")
    for table in DEAD_TABLES:
        op.drop_table(table, schema=schema)


def downgrade() -> None:
    """降级只重建空表结构，不恢复数据 (recreates empty schemas only; data is not restored)."""
    _use_schema()
    bind = op.get_bind()
    for stmt in _DOWNGRADE_DDL:
        bind.exec_driver_sql(stmt)
    for table, constraint, defn in _LIVE_FOREIGN_KEYS:
        bind.exec_driver_sql(f"ALTER TABLE {table} ADD CONSTRAINT {constraint} {defn}")
